+	model := loginURLActionModel{}
+	finalModel, err := tea.NewProgram(
+		model,
+		tea.WithContext(ctx),
+		tea.WithInput(tty),
+		tea.WithOutput(io.Discard),
+		tea.WithoutSignalHandler(),
+	).Run()
+	if ctx.Err() != nil {
